#pragma once
#include <string>
#include <vector>

struct TKRequest {
    std::string model;                 // "glm-4.7-fp8"
    std::vector<int> input_ids;        // tokenizált prompt
    int max_tokens;
    float temperature;
    float top_p;
    int top_k;
    bool stream;
};

struct TKResponse {
    std::vector<int> output_ids;
};

class TKEngine {
public:
    TKEngine(const std::string& model_dir,
             int tensor_parallel_size,
             float gpu_mem_fraction);

    void initialize_runtime();  // CUDA, NCCL, TK runtime init
    void load_model();          // FP8 súlyok betöltése HF snapshotból [web:40][web:45]
    void run_inference(const TKRequest& req, TKResponse& res); // continuous batching, FP8 Tensor Core, KV cache [web:45][web:47]
    void shutdown();

private:
    std::string model_dir_;
    int tp_;
    float gpu_mem_fraction_;

    // GPU context, CUDA stream-ek, NCCL communicator-ok stb.
    // KV cache struktúrák, model weight shard-ok, tile layout metaadatok
};

