tk_engine/main_server.cpp (OPENAI /V1/CHAT/COMPLETIONS)

#include "tk_infer.hpp"
#include <httplib.h>      // pl. yhirose/cpp-httplib (egyetlen header)
#include <nlohmann/json.hpp>

using json = nlohmann::json;

int main(int argc, char** argv) {
    std::string model_dir = "/model/zai-org__GLM-4.7-FP8";
    std::string host = "0.0.0.0";
    int port = 8000;
    int tp = 8;
    float gpu_mem_fraction = 0.95f;

    // nagyon primitív arg parse (lehet normálisabb is)
    for (int i = 1; i < argc; ++i) {
        std::string a = argv[i];
        if (a == "--model-dir" && i + 1 < argc) model_dir = argv[++i];
        else if (a == "--host" && i + 1 < argc) host = argv[++i];
        else if (a == "--port" && i + 1 < argc) port = std::stoi(argv[++i]);
        else if (a == "--tensor-parallel-size" && i + 1 < argc) tp = std::stoi(argv[++i]);
        else if (a == "--gpu-mem-fraction" && i + 1 < argc) gpu_mem_fraction = std::stof(argv[++i]);
    }

    TKEngine engine(model_dir, tp, gpu_mem_fraction);
    engine.initialize_runtime();
    engine.load_model();

    httplib::Server svr;

    svr.Post("/v1/chat/completions", [&engine](const httplib::Request& req, httplib::Response& res) {
        try {
            auto j = json::parse(req.body);

            std::string model_name = j.value("model", "glm-4.7-fp8");
            auto messages = j.at("messages");
            std::string prompt;

            // utolsó user message → prompt
            for (auto& m : messages) {
                if (m.value("role", "") == "user") {
                    prompt = m.value("content", "");
                }
            }

            int max_tokens = j.value("max_tokens", 512);
            float temperature = j.value("temperature", 1.0f);
            float top_p = j.value("top_p", 1.0f);
            int top_k = j.value("top_k", 50);
            bool stream = j.value("stream", false);

            TKRequest tk_req;
            tk_req.model = model_name;
            // TODO: tokenizálás C++-ban (HF tokenizer offline/export), most dummy:
            // tk_req.input_ids = tokenize(prompt);
            tk_req.max_tokens = max_tokens;
            tk_req.temperature = temperature;
            tk_req.top_p = top_p;
            tk_req.top_k = top_k;
            tk_req.stream = stream;

            TKResponse tk_res;
            engine.run_inference(tk_req, tk_res);

            // TODO: detokenizálás: output_ids → text
            std::string completion_text = "<detokenized-output>";

            json out;
            out["id"] = "chatcmpl-native";
            out["object"] = "chat.completion";
            out["created"] = (int)time(nullptr);
            out["model"] = model_name;
            out["choices"] = json::array();
            json choice;
            choice["index"] = 0;
            choice["finish_reason"] = "stop";
            choice["message"] = {
                {"role", "assistant"},
                {"content", completion_text}
            };
            out["choices"].push_back(choice);

            json usage;
            usage["prompt_tokens"] = 0;
            usage["completion_tokens"] = (int)tk_res.output_ids.size();
            usage["total_tokens"] = usage["prompt_tokens"].get<int>() + usage["completion_tokens"].get<int>();
            out["usage"] = usage;

            res.set_content(out.dump(), "application/json");
        } catch (const std::exception& e) {
            json err;
            err["error"] = e.what();
            res.status = 500;
            res.set_content(err.dump(), "application/json");
        }
    });

    svr.listen(host.c_str(), port);

    engine.shutdown();
    return 0;
}

----------------------------------------------------------------
3. TKENGINE BELSEJE (NAGYVONALÚAN, FP8 + 8× B200)

- initialize_runtime():
  - CUDA init 8 GPU-ra, saját stream-ek.
  - NCCL init, TP=8 communicators.
  - ThunderKittens-style runtime: tile allocator, pipeline scheduler, CUDA Graph capture előkészítése [web:21][web:22][web:47].

- load_model():
  - HF snapshotból FP8 súlyok beolvasása: zai-org/GLM-4.7-FP8 (W8A8) [web:40][web:45].
  - Súlyok shard-olása 8 GPU között (tensor-parallel) [web:47].
  - Tile layout: 16×16 / 64×64 FP8 blokkokra rendezés, scale/meta betöltése [web:22][web:36].

- run_inference():
  - Session létrehozása (KV cache slotok allokálása GPU-n, paged layout) [web:27][web:47].
  - Continuous batching: a futó sessionök kész token-stepjeit egy batch-be pakolja.
  - Egy token-step:
    - CUDA Graph launch: fused attention + FFN + LN + residual + sampling.
    - Attention:
      - Q/K/V projekció FP8 WGMMA-val.
      - KV cache update (paged FP8/int8, per-page scale).
      - Softmax + V aggregáció tile-on, minimális DRAM IO-val.
    - FFN blokk fused GEMM+aktiváció+GEMM.
    - GPU-oldali sampling (logits → top-k/top-p/temperature → token ID).
  - Loop max_tokens-ig, amíg EOS vagy limit.

- A célzott 3000+ tok/s:
  - FP8 Tensor Core kihajtása (W8A8 path) [web:45].
  - Continuous batching + CUDA Graph csökkenti overheadet [web:31][web:47].
  - 8× B200 tensor-parallel, optimalizált NCCL ütemezéssel [web:16][web:47].

